file.contenuto:
extends Node2D

@onready var channel_player: AudioStreamPlayer = $ChannelPlayer
var jump_stream: AudioStream = preload("res://assets/audio/jump.wav")
var hit_stream: AudioStream = preload("res://assets/audio/hit.wav")


func _ready() -> void:
	channel_player.play()


func player_jump() -> void:
	channel_player.stream = jump_stream
	channel_player.play()


func player_hit() -> void:
	channel_player.stream = hit_stream
	channel_player.pitch_scale = 0.1
	channel_player.play()

extends Node2D

@onready var music_player: AudioStreamPlayer = $MusicPlayer
@onready var jump_player: AudioStreamPlayer = $JumpPlayer
@onready var hit_player: AudioStreamPlayer = $HitPlayer


func _ready() -> void:
	music_player.play()


func player_jump() -> void:
	jump_player.play()


func player_hit() -> void:
	hit_player.pitch_scale = 1.0
	hit_player.play()
